import{_ as t,o as a,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0042 — Médiathèque, lot 2 : l'IA lit les octets, une image de partage résolue une fois, des médias joints à la résolution","description":"Extrait de docs/adr/0042-mediatheque-branchements.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0042 — Médiathèque, lot 2 : l'IA lit les octets, une image de partage résolue une fois, des médias joints à la résolution","description":"Extrait de docs/adr/0042-mediatheque-branchements.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0042-mediatheque-branchements.md","filePath":"developpeurs/adr/0042-mediatheque-branchements.md"}`),o={name:"developpeurs/adr/0042-mediatheque-branchements.md"};function s(d,e,r,l,u,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0042--médiathèque-lot-2--lia-lit-les-octets-une-image-de-partage-résolue-une-fois-des-médias-joints-à-la-résolution" tabindex="-1">ADR-0042 — Médiathèque, lot 2 : l&#39;IA lit les octets, une image de partage résolue une fois, des médias joints à la résolution <a class="header-anchor" href="#adr-0042--médiathèque-lot-2--lia-lit-les-octets-une-image-de-partage-résolue-une-fois-des-médias-joints-à-la-résolution" aria-label="Permalink to &quot;ADR-0042 — Médiathèque, lot 2 : l&#39;IA lit les octets, une image de partage résolue une fois, des médias joints à la résolution {#adr-0042--médiathèque-lot-2--lia-lit-les-octets-une-image-de-partage-résolue-une-fois-des-médias-joints-à-la-résolution}&quot;">​</a></h1><p><strong>Date :</strong> 23 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §5.4, §11.1, §14.4, §14.9.1 ; audit SEO du 18/09/2026, constat S12 ; prolonge l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> (lot 2 de ses actions liées), s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration">ADR-0013</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0041 a livré le socle de la médiathèque. Son lot 2 devait la brancher sur le reste du CMS : texte alternatif proposé par l&#39;IA <strong>appliqué</strong> au média, image de remplacement par type de contenu, image de partage Open Graph (constat S12), enclosures RSS, extraction documentaire pour la recherche, expansion des médias dans <code>/public/resolve</code>. Deux écarts relevés au lot 1 restaient aussi ouverts : <code>pages.image_id</code> n&#39;était pas vérifié à l&#39;écriture, et l&#39;image de remplacement d&#39;une vue liste restait une saisie d&#39;UUID, que la recherche des usages ne lisait pas.</p><p>Le Product Owner a retenu les branchements. Deux chantiers en sont sortis, parce qu&#39;ils demandent chacun une décision de fond :</p><ul><li><strong>L&#39;extraction documentaire.</strong> Aucun vrai fournisseur d&#39;OCR n&#39;est branché. Lire un PDF sans OCR demande une dépendance (<code>pypdf</code>) que le Core n&#39;a pas. Et l&#39;index unique de <code>search_index.document_id</code> contredit une médiathèque partagée entre les sites : une ligne d&#39;index appartient à un seul site.</li><li><strong>La vidéo.</strong> La servir demande les requêtes <code>Range</code>.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le fournisseur d&#39;IA reçoit les octets de l&#39;image, lus par le Core au moment de l&#39;appel</strong> (décision du Product Owner). L&#39;API d&#39;une collectivité n&#39;est généralement pas joignable depuis Internet : une URL que le fournisseur téléchargerait lui-même ne marcherait pas.</p><ul><li>Un média se désigne par une référence opaque <code>media:{uuid}</code> (<code>app/ai/ports.py</code>). <code>ImageReference</code> la reconnaît, et refuse toujours une charge en ligne (<code>data:</code>, <code>base64:</code>).</li><li>Le <code>ProviderManager</code> lit les octets (<code>app/media/vision.py</code>, <code>resolve_media_image</code>) <strong>après</strong> la résolution de la politique, la souveraineté, le budget et le disjoncteur. Rien n&#39;est donc lu pour un appel qui ne partira pas, et une image n&#39;est lue qu&#39;une fois, même en cas de reprise ou de repli. L&#39;organisation est celle de l&#39;invocation : un média d&#39;une autre collectivité est introuvable, comme un média inexistant.</li><li>Les octets voyagent dans un <code>ImageBytes</code>, remis à <code>VisionPort.describe(…, image=…)</code> <strong>à côté</strong> de <code>VisionInput</code>, jamais dedans. <code>ImageBytes</code> n&#39;est pas un modèle Pydantic : aucune sérialisation ne peut le faire entrer dans <code>ai_jobs</code>, dans <code>ai_suggestions</code> ou dans un journal. Sa représentation textuelle ne montre que le type et la taille. C&#39;est l&#39;adaptateur qui met les octets au format de son fournisseur : une data URL pour OpenAI.</li><li>Les formats forment une liste fermée : PNG, JPEG, GIF, WebP. Le SVG est refusé, parce qu&#39;aucun fournisseur ne le décrit. Plafond : <code>VISION_IMAGE_MAX_BYTES</code> (20 Mio, la limite d&#39;OpenAI), opposé à la taille enregistrée puis au flux lu. Un refus certain est dit à l&#39;écran avant toute invocation. Il n&#39;ouvre aucune ligne de journal IA.</li><li>Une référence qui n&#39;est pas <code>media:</code> garde le comportement d&#39;avant : elle part telle quelle.</li></ul><p><strong>2. Proposer, puis appliquer, sous l&#39;adresse du média.</strong></p><ul><li><code>POST /media/{id}/alt-text/suggest</code> dépose une suggestion (tâche <code>alt_text</code>, régime <code>optional</code>) et rend l&#39;issue de l&#39;invocation. Sans fournisseur, l&#39;issue vaut <code>unavailable</code>, avec un 200. La route exige <code>media.write</code> <strong>et</strong> <code>ai.invoke</code>, comme toute sollicitation d&#39;un modèle : sans cette seconde permission, un rôle qui peut déposer un média pourrait dépenser le budget IA et envoyer une image chez un fournisseur. Les rôles intégrés ne l&#39;ont pas, sauf Admin.</li><li><code>POST /media/{id}/alt-text/apply</code> écrit une suggestion <strong>acceptée</strong> dans le média et exige <code>media.write</code>. Le texte va dans <code>alt_text</code> pour la langue de référence, dans <code>translations[langue].alt_text</code> sinon. La langue de référence d&#39;un média est la langue par défaut des sites de l&#39;organisation quand ils s&#39;accordent tous sur une même langue, sinon celle du Core (<code>fr</code>). Refus : suggestion en attente, rejetée ou expirée (409), suggestion d&#39;une autre tâche ou d&#39;un autre média (422), média décoratif (409, RGAA 1.2).</li><li>Les deux routes vivent dans <code>app/api/ai_editorial.py</code>. Un test d&#39;architecture interdit à une route du Core d&#39;importer le socle IA (CDC §14.4) : c&#39;est le même parti que la route d&#39;application du SEO. Elles gardent le 404 unique de la médiathèque.</li></ul><p><strong>3. L&#39;image d&#39;un contenu est résolue une seule fois, pour toutes les surfaces</strong> (<code>app/media/seo.py</code>). Pas de champ nouveau (décision du Product Owner). Pour une fiche, dans cet ordre :</p><ol><li>l&#39;image principale du panneau (<code>settings.image_id</code>) ;</li><li>la première valeur du premier champ <code>media</code> ou <code>media_gallery</code> <strong>rempli</strong> du schéma ;</li><li>l&#39;image de remplacement du type (<code>ListingHeader.fallback_media_id</code>).</li></ol><p>Une page n&#39;a qu&#39;une source : <code>page.image_id</code>. Un candidat qui ne désigne pas une image de l&#39;organisation est sauté : des contenus anciens citent des UUID qui ne désignent rien. L&#39;alternative est rendue dans la langue servie si le média en porte une traduction, sinon dans la langue de référence. Elle est vide pour un média décoratif.</p><p><strong>4. Deux surfaces lisent cette résolution.</strong></p><ul><li><strong>Open Graph (S12).</strong> <code>ResolvedSeo.image</code> de <code>/public/resolve</code> porte <code>media_id</code>, <code>path</code> (le <code>public_url</code>), <code>url</code> (absolue sur le domaine du site, <code>null</code> sans domaine, comme <code>canonical</code>), <code>alt</code>, <code>width</code>, <code>height</code> et <code>mime_type</code>.</li><li><strong>RSS.</strong> Chaque article porte <code>&lt;enclosure url length type&gt;</code>, seulement si l&#39;URL absolue existe (comme <code>&lt;link&gt;</code>). Les images de toute une page de flux sont chargées en <strong>une</strong> requête.</li></ul><p><strong>5. <code>/public/resolve</code> joint les médias cités.</strong> Une réponse <code>entry</code> ou <code>page</code> porte <code>media</code>, un dictionnaire des métadonnées publiques (le modèle de <code>GET /public/media</code>, réutilisé) de chaque média cité. Pour une fiche : ses données <strong>expurgées</strong> (jamais un champ privé), <code>settings.image_id</code> et l&#39;image de partage. Pour une page : sa composition enregistrée et <code>image_id</code>. Un seul lot, borné à l&#39;organisation. Une pièce jointe d&#39;usager (ADR-0038) n&#39;est pas un média et n&#39;y figure pas.</p><p><strong>6. Les dernières références d&#39;image sont vérifiées, et comptées dans les usages.</strong></p><ul><li><code>pages.image_id</code> est vérifié à la création et à la modification d&#39;une page, comme les blocs (422).</li><li>L&#39;entête d&#39;une vue liste (<code>header.image_id</code>, <code>header.fallback_media_id</code>) est vérifié à la création d&#39;un type et à l&#39;écriture de son <code>listing_config</code> (422, rattaché au champ).</li><li><code>media_usages</code> lit aussi <code>content_types.listing_config</code>, sous un genre d&#39;usage <code>content_type</code>. Une image de remplacement en service ne se supprime donc pas (409).</li><li>Côté back-office, <code>ListingHeaderEditor.vue</code> emploie le sélecteur de médias au lieu d&#39;une saisie d&#39;UUID. La liste des usages renvoie vers la vue liste du type.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Une URL publique absolue que le fournisseur télécharge</strong> (nouveau réglage <code>MEDIA_PUBLIC_BASE_URL</code>)</td><td>Elle respecte le principe « une référence, jamais des octets ». Mais elle suppose une API joignable depuis Internet, ce qui n&#39;est pas le cas courant d&#39;une collectivité : la fonction serait restée indisponible là où elle sert. Décision du Product Owner.</td></tr><tr><td><strong>Lire les octets dans l&#39;appelant</strong></td><td>Ils auraient voyagé dans <code>AiInvocation</code>, une structure que le gestionnaire journalise et dont il sérialise l&#39;entrée.</td></tr><tr><td><strong>Lire les octets dans l&#39;adaptateur</strong></td><td>L&#39;adaptateur ne connaît ni la base ni l&#39;organisation (<code>ModelCall</code> n&#39;en porte aucune, exprès). Lui confier la lecture aurait été lui confier l&#39;isolation entre collectivités.</td></tr><tr><td><strong>Mettre les routes d&#39;alternative dans <code>app/api/media.py</code></strong></td><td>Une route du Core n&#39;importe pas le socle IA (CDC §14.4, vérifié par un test d&#39;architecture).</td></tr><tr><td><strong>Proposer une alternative avec <code>media.write</code> seul</strong></td><td>Un Auteur aurait pu solliciter un modèle et dépenser le budget IA, ce que toutes les autres fonctions réservent à <code>ai.invoke</code>.</td></tr><tr><td><strong>Un champ dédié <code>settings.seo.og_image_id</code></strong></td><td>Un champ et un écran de plus pour un besoin que la chaîne de repli couvre. Décision du Product Owner. Il reste possible sans rien casser : il prendrait la tête de la chaîne.</td></tr><tr><td><strong>Une résolution d&#39;image propre à chaque surface</strong></td><td>Un flux finirait par annoncer une image que la page ne porte pas. C&#39;est la raison qui a déjà réuni la description dans <code>app/content/seo.py</code> (ADR-0035).</td></tr><tr><td><strong>Brancher l&#39;extraction documentaire dans ce lot</strong></td><td>Pas de fournisseur d&#39;OCR réel, une dépendance à trancher, et un index unique incompatible avec un fonds partagé entre sites. Reportée.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une image sans alternative se corrige en deux gestes depuis sa fiche, et l&#39;alternative acceptée sert partout où le média est cité.</li><li>La fonction marche sur une API fermée à Internet. Les octets d&#39;une image ne laissent aucune trace dans le CMS.</li><li>Un contenu partagé sur un réseau social porte une image et son alternative (S12). Un flux RSS porte la même image que la page.</li><li>Un front obtient en un seul appel le contenu d&#39;une adresse et les métadonnées de tous ses médias.</li><li>Plus aucune référence d&#39;image n&#39;est une saisie d&#39;UUID non vérifiée, et aucune image en service ne se supprime.</li></ul><p><strong>Négatives</strong></p><ul><li>Les octets d&#39;une image partent chez le fournisseur retenu par la politique de l&#39;organisation. C&#39;est le principe même de la tâche, et la souveraineté (mode local seulement) s&#39;applique avant toute lecture. Un Admin doit le savoir en activant un fournisseur hors de l&#39;Union.</li><li>Les rôles Éditeur et Auteur ne voient pas le bouton de proposition tant qu&#39;on ne leur donne pas <code>ai.invoke</code>.</li><li>La langue de référence d&#39;un média est recalculée à l&#39;application. Si les sites changent de langue par défaut entre la proposition et l&#39;application, l&#39;alternative peut changer de destination.</li><li>La référence <code>media:</code> n&#39;est résolue que pour la vision. En OCR ou en transcription, elle partirait telle quelle chez le fournisseur. C&#39;est sans objet aujourd&#39;hui, puisqu&#39;aucun écran ne le propose.</li><li>L&#39;expansion d&#39;une page lit la composition <strong>enregistrée</strong>. Elle peut donc joindre un média qu&#39;un bloc masqué au rendu cite. Ce n&#39;est pas une fuite, un média est public par nature (ADR-0041, §10).</li><li>Recette faite par les tests seulement. L&#39;écran n&#39;a pas été éprouvé dans un navigateur, et l&#39;image <code>cms-admin</code> est à reconstruire.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Alternative proposée par l&#39;IA et appliquée au média : <code>app/media/vision.py</code>, <code>app/media/alt_text.py</code>, octets passés par le <code>ProviderManager</code> (<code>app/ai/manager.py</code>) et encodés par l&#39;adaptateur OpenAI, routes <code>POST /media/{id}/alt-text/suggest</code> et <code>/apply</code> (<code>app/api/ai_editorial.py</code>), boutons sur la fiche média — recette <code>apps/api/tests/test_mediatheque_alt_ia.py</code>.</li><li>[x] Image de partage (S12), enclosures RSS, expansion des médias dans <code>/public/resolve</code>, entête de vue liste et <code>pages.image_id</code> vérifiés, usages de <code>listing_config</code> — <code>app/media/seo.py</code>, <code>app/api/public_resolve.py</code>, <code>app/listing/rss.py</code>, <code>app/media/service.py</code>, <code>app/media/references.py</code> ; sélecteur dans <code>ListingHeaderEditor.vue</code> — recette <code>apps/api/tests/test_mediatheque_surfaces.py</code>.</li><li>[x] Extraction documentaire des médias pour la recherche : choisir entre une dépendance de lecture (<code>pypdf</code>) et un fournisseur d&#39;OCR réel, et lever la contradiction entre l&#39;index unique de <code>search_index.document_id</code> et un fonds partagé entre les sites — fait le 23/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0043-extraction-documentaire-native-et-tika">ADR-0043</a> : <code>pypdf</code> dans le Core et Apache Tika livré inactif, une ligne d&#39;index par site (<code>(document_id, site_id)</code>, migration <code>0035</code>) ; recettes <code>tests/test_mediatheque_extraction.py</code> et <code>tests/test_extraction_tika.py</code>.</li><li>[ ] Recette manuelle dans un navigateur de la fiche média (proposer, accepter et appliquer) et du sélecteur de l&#39;entête de liste, après reconstruction de l&#39;image <code>cms-admin</code>.</li></ul>',28)])])}const g=t(o,[["render",s]]);export{m as __pageData,g as default};
